.lf__liquid{position:absolute;left:0;right:0;top:0;bottom:0;transform:translateY(100%);animation:lf-rise var(--p-cycle,5s) ease-in-out infinite}
.lf__wave{position:absolute;left:50%;top:-5px;width:240px;height:240px;margin-left:-120px;border-radius:var(--p-round,42%);background:var(--p-color,var(--primary));opacity:.9;animation:lf-spin var(--p-wave,3s) linear infinite}
.lf__wave--b{border-radius:38%;opacity:.5;animation-duration:calc(var(--p-wave,3s) * 1.4)}
@keyframes lf-rise{0%,8%{transform:translateY(100%)}70%,92%{transform:translateY(calc(100% - var(--p-fill,75%)))}100%{transform:translateY(100%)}}
@keyframes lf-spin{to{transform:rotate(1turn)}}
